// This file is not generated by Speakeasy — it adds the `vf docs` command
// group: in-band access to the Voiceflow documentation so humans and AI
// coding agents can look things up mid-task without leaving the terminal.
//
// Zero bundled content: `search` calls the public docs search endpoint and
// `get` fetches a page's markdown rendition. No authentication is required
// or sent.

package cli

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"path"
	"strings"
	"time"

	"github.com/spf13/cobra"
	"github.com/voiceflow/cli/internal/flagutil"
	"github.com/voiceflow/cli/internal/output"
)

const (
	docsBaseURL       = "https://www.voiceflow.com/docs"
	docsSearchMCPURL  = "https://www.voiceflow.com/docs/mcp"
	docsSearchTool    = "search_voiceflow"
	docsClientTimeout = 15 * time.Second

	// docsSearchWhy is the one-sentence goal the search tool requires with
	// every call. vf cannot know the user's task, so it names its own.
	docsSearchWhy = "Look up Voiceflow documentation from the vf CLI"
)

// initDocsCmd registers the docs command group.
func initDocsCmd(parent *cobra.Command) {
	docsCmd := &cobra.Command{
		Use:   "docs",
		Short: "Search and read the Voiceflow documentation from the terminal",
		Long: `Search and read the Voiceflow documentation without leaving the terminal.

No authentication is required — these commands work before any token is set up.

Subcommands:
  search  - Full-text search across the documentation
  get     - Print one documentation page as markdown`,
	}
	parent.AddCommand(docsCmd)

	docsCmd.AddCommand(&cobra.Command{
		Use:   "search <query>",
		Short: "Search the Voiceflow documentation",
		Long: `Search the Voiceflow documentation and print matching pages with their
titles, links, and content excerpts.

Pass --output-format json for structured results ({title, link, page, content}).
Fetch any result in full with: vf docs get <page>`,
		Example: `  vf docs search "personal access token"
  vf docs search "publish an environment" --output-format json`,
		Args: cobra.MinimumNArgs(1),
		RunE: runDocsSearchCmd,
	})

	docsCmd.AddCommand(&cobra.Command{
		Use:   "get <page>",
		Short: "Print a documentation page as markdown",
		Long: `Fetch one documentation page and print its markdown to stdout.

Accepts a page path (from 'vf docs search' output) or a full
voiceflow.com/docs URL.`,
		Example: `  vf docs get api-reference/authentication
  vf docs get cli/commands/workspace
  vf docs get https://www.voiceflow.com/docs/cli/overview`,
		Args: cobra.ExactArgs(1),
		RunE: runDocsGetCmd,
	})
}

// docsSearchResult is one search hit as vf prints it.
type docsSearchResult struct {
	Title   string `json:"title"`
	Link    string `json:"link"`
	Page    string `json:"page"`
	Content string `json:"content"`
}

// docsSearchHit is one entry of the search tool's structuredContent.results.
type docsSearchHit struct {
	Title   string `json:"title"`
	URL     string `json:"url"`
	PageURL string `json:"pageUrl"`
	Snippet string `json:"snippet"`
}

// runDocsSearchCmd executes docs search via the public documentation search
// endpoint (a stateless JSON-RPC tool call).
func runDocsSearchCmd(cmd *cobra.Command, args []string) error {
	query := strings.Join(args, " ")

	request, err := json.Marshal(map[string]interface{}{
		"jsonrpc": "2.0",
		"id":      1,
		"method":  "tools/call",
		"params": map[string]interface{}{
			"name":      docsSearchTool,
			"arguments": docsSearchArguments(query),
		},
	})
	if err != nil {
		return err
	}

	httpRequest, err := http.NewRequestWithContext(cmd.Context(), http.MethodPost, docsSearchMCPURL, bytes.NewReader(request))
	if err != nil {
		return err
	}
	httpRequest.Header.Set("Content-Type", "application/json")
	httpRequest.Header.Set("Accept", "application/json, text/event-stream")

	body, err := doDocsRequest(httpRequest)
	if err != nil {
		return err
	}

	results, err := parseDocsSearchResponse(body)
	if err != nil {
		return err
	}
	if output.WantsRawJSON(cmd) {
		return writeDocsSearchJSON(cmd, results)
	}
	if len(results) == 0 {
		fmt.Fprintf(cmd.OutOrStdout(), "No documentation matches for %q. Browse everything at %s\n", query, docsBaseURL)
		return nil
	}

	out := cmd.OutOrStdout()
	for i, result := range results {
		if i > 0 {
			fmt.Fprint(out, "\n---\n\n")
		}
		fmt.Fprintf(out, "Title: %s\nLink: %s\nPage: %s\nContent: %s\n", result.Title, result.Link, result.Page, result.Content)
	}
	fmt.Fprintln(out, "\nRead a full page with: vf docs get <page>")
	return nil
}

// writeDocsSearchJSON prints results as JSON, through the --jq expression when
// one is set, the way other commands apply it. No matches print as [], so a
// caller that parses stdout always gets JSON.
func writeDocsSearchJSON(cmd *cobra.Command, results []docsSearchResult) error {
	out := cmd.OutOrStdout()
	expression, _ := flagutil.GetStringFlag(cmd, "jq")
	if expression == "" {
		encoded, err := json.MarshalIndent(results, "", "  ")
		if err != nil {
			return err
		}
		fmt.Fprintln(out, string(encoded))
		return nil
	}
	filtered, err := output.ApplyJqFilter(results, expression)
	if err != nil {
		return err
	}
	for _, value := range filtered {
		encoded, err := json.MarshalIndent(value, "", "  ")
		if err != nil {
			return err
		}
		fmt.Fprintln(out, string(encoded))
	}
	return nil
}

// docsSearchArguments builds the search tool's arguments. Besides the query,
// the tool requires who is asking and why: an agent that runs vf chose to
// search on its own, so agent mode reports "agent", and anything else "human".
func docsSearchArguments(query string) map[string]string {
	initiator := "human"
	if output.IsAgentMode() {
		initiator = "agent"
	}
	return map[string]string{
		"initiator": initiator,
		"purpose":   "answers",
		"why":       docsSearchWhy,
		"question":  query,
	}
}

// runDocsGetCmd fetches one page's markdown rendition and prints it.
func runDocsGetCmd(cmd *cobra.Command, args []string) error {
	pageURL, err := docsPageURL(args[0])
	if err != nil {
		return err
	}

	httpRequest, err := http.NewRequestWithContext(cmd.Context(), http.MethodGet, pageURL, nil)
	if err != nil {
		return err
	}

	body, err := doDocsRequest(httpRequest)
	if err != nil {
		return err
	}
	fmt.Fprintln(cmd.OutOrStdout(), strings.TrimSpace(string(body)))
	return nil
}

// docsPageURL normalizes a page argument (path or full URL) to its markdown
// rendition URL. Full URLs are validated by their PARSED components — scheme,
// host, and path — never by substring matching, and the returned URL is
// rebuilt from those components so nothing unvalidated reaches the wire.
func docsPageURL(page string) (string, error) {
	page = strings.TrimSpace(page)
	if page == "" {
		return "", fmt.Errorf("empty page — pass a path like api-reference/authentication (find pages with: vf docs search <query>)")
	}

	if strings.HasPrefix(page, "http://") || strings.HasPrefix(page, "https://") {
		parsed, err := url.Parse(page)
		if err != nil {
			return "", fmt.Errorf("invalid URL %q: %w", page, err)
		}
		hostname := strings.ToLower(parsed.Hostname())
		if parsed.Scheme != "https" || parsed.User != nil ||
			(hostname != "www.voiceflow.com" && hostname != "voiceflow.com") {
			return "", fmt.Errorf("only https://www.voiceflow.com/docs URLs are supported (got %s)", page)
		}
		cleanPath := path.Clean("/" + parsed.EscapedPath())
		if cleanPath != "/docs" && !strings.HasPrefix(cleanPath, "/docs/") {
			return "", fmt.Errorf("only https://www.voiceflow.com/docs URLs are supported (got %s)", page)
		}
		if !strings.HasSuffix(cleanPath, ".md") {
			cleanPath += ".md"
		}
		// Query and fragment carry nothing for a docs page; drop them so the
		// .md suffix always lands on the path.
		return "https://www.voiceflow.com" + cleanPath, nil
	}

	page = strings.Trim(page, "/")
	page = strings.TrimPrefix(page, "docs/")
	cleanPath := path.Clean("/" + page)
	if cleanPath == "/" || strings.HasPrefix(cleanPath, "/..") {
		return "", fmt.Errorf("invalid page path %q — pass a path like api-reference/authentication", page)
	}
	if !strings.HasSuffix(cleanPath, ".md") {
		cleanPath += ".md"
	}
	return docsBaseURL + cleanPath, nil
}

// doDocsRequest performs an HTTP request against the docs site with a bounded
// timeout, returning the response body or an error that names the fix.
func doDocsRequest(request *http.Request) ([]byte, error) {
	client := &http.Client{Timeout: docsClientTimeout}
	response, err := client.Do(request)
	if err != nil {
		return nil, fmt.Errorf("could not reach the Voiceflow documentation (%w) — check network connectivity; the docs are also at %s", err, docsBaseURL)
	}
	defer response.Body.Close()

	body, err := io.ReadAll(io.LimitReader(response.Body, 4<<20))
	if err != nil {
		return nil, fmt.Errorf("could not read the documentation response: %w", err)
	}
	if response.StatusCode == http.StatusNotFound {
		return nil, fmt.Errorf("documentation page not found (%s) — find valid pages with: vf docs search <query>", request.URL)
	}
	if response.StatusCode >= 400 {
		return nil, fmt.Errorf("the documentation site returned HTTP %d — this is usually transient; the docs are also at %s", response.StatusCode, docsBaseURL)
	}
	return body, nil
}

// parseDocsSearchResponse extracts the search hits from a JSON-RPC tools/call
// response, handling both plain JSON and SSE-framed ("data: {...}") bodies.
func parseDocsSearchResponse(body []byte) ([]docsSearchResult, error) {
	payload, err := docsSearchResponsePayload(body)
	if err != nil {
		return nil, err
	}

	var response struct {
		Result struct {
			Content []struct {
				Type string `json:"type"`
				Text string `json:"text"`
			} `json:"content"`
			StructuredContent *struct {
				Results []docsSearchHit `json:"results"`
			} `json:"structuredContent"`
			IsError bool `json:"isError"`
		} `json:"result"`
		Error *struct {
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.Unmarshal(payload, &response); err != nil {
		return nil, fmt.Errorf("unexpected response from the documentation search endpoint: %w", err)
	}
	if response.Error != nil {
		return nil, fmt.Errorf("documentation search failed: %s", response.Error.Message)
	}
	// A tool that fails says so inside a successful JSON-RPC result. Read
	// without this check, the failure text printed as if it were a search hit
	// and the command exited 0.
	if response.Result.IsError {
		var reasons []string
		for _, content := range response.Result.Content {
			if content.Type == "text" && strings.TrimSpace(content.Text) != "" {
				reasons = append(reasons, strings.TrimSpace(content.Text))
			}
		}
		if len(reasons) == 0 {
			reasons = []string{"the search tool reported an error without saying why"}
		}
		return nil, fmt.Errorf("documentation search failed: %s — the docs are also at %s", strings.Join(reasons, "; "), docsBaseURL)
	}
	if response.Result.StructuredContent == nil {
		return nil, fmt.Errorf("unexpected response from the documentation search endpoint: no structured results — the docs are also at %s", docsBaseURL)
	}

	hits := response.Result.StructuredContent.Results
	results := make([]docsSearchResult, 0, len(hits))
	for _, hit := range hits {
		// The page comes from the hit's link when it has no page URL of its
		// own; docsPagePath drops the link's #section.
		page := hit.PageURL
		if page == "" {
			page = hit.URL
		}
		results = append(results, docsSearchResult{
			Title:   hit.Title,
			Link:    hit.URL,
			Page:    docsPagePath(page),
			Content: hit.Snippet,
		})
	}
	return results, nil
}

// docsSearchResponsePayload returns the JSON-RPC response in body, which is
// either one JSON object or a stream of server-sent events. A stream may carry
// other messages before the response, such as progress notifications, and may
// split one message across several data: lines. The response is the first
// message that carries a result or an error; notifications carry neither.
func docsSearchResponsePayload(body []byte) ([]byte, error) {
	trimmed := bytes.TrimSpace(body)
	if bytes.HasPrefix(trimmed, []byte("{")) {
		return trimmed, nil
	}
	for _, event := range serverSentEventData(body) {
		var message struct {
			Result json.RawMessage `json:"result"`
			Error  json.RawMessage `json:"error"`
		}
		if json.Unmarshal(event, &message) == nil && (message.Result != nil || message.Error != nil) {
			return event, nil
		}
	}
	return nil, fmt.Errorf("unexpected response from the documentation search endpoint: it held no reply to the search — the docs are also at %s", docsBaseURL)
}

// serverSentEventData returns the data of each event in an SSE stream: its
// data: lines joined by newlines, as the format defines.
func serverSentEventData(body []byte) [][]byte {
	var events, lines [][]byte
	endEvent := func() {
		if len(lines) > 0 {
			events = append(events, bytes.Join(lines, []byte("\n")))
			lines = nil
		}
	}
	for _, line := range bytes.Split(body, []byte("\n")) {
		line = bytes.TrimSuffix(line, []byte("\r"))
		if len(line) == 0 {
			endEvent()
			continue
		}
		if data, isData := bytes.CutPrefix(line, []byte("data:")); isData {
			lines = append(lines, bytes.TrimPrefix(data, []byte(" ")))
		}
	}
	endEvent()
	return events
}

// docsPagePath turns a hit's page URL into the argument 'vf docs get' takes:
// https://www.voiceflow.com/docs/api-reference/authentication becomes
// api-reference/authentication. Any other URL is returned whole, and 'vf docs
// get' decides whether it can fetch it.
func docsPagePath(pageURL string) string {
	page, isDocsPage := strings.CutPrefix(pageURL, docsBaseURL+"/")
	if !isDocsPage {
		return pageURL
	}
	if end := strings.IndexAny(page, "?#"); end >= 0 {
		page = page[:end]
	}
	return page
}
